-- Baseline of the Library Management System schema as it existed before Flyway.
--
-- Existing databases:
--   spring.flyway.baseline-on-migrate=true and baseline-version=1 cause Flyway to
--   record this version as an already-applied baseline instead of executing it.
--
-- Fresh databases:
--   Flyway executes this migration to create the same schema from scratch.
--
-- Do not edit this file after it has been applied. Add a new V2__*.sql migration.

CREATE TABLE public.author (
    id integer NOT NULL,
    name character varying(255)
);

ALTER TABLE public.author ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.author_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);

CREATE TABLE public.book (
    id integer NOT NULL,
    name character varying(255),
    price double precision NOT NULL,
    author_id integer,
    user_id integer
);

ALTER TABLE public.book ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.book_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);

CREATE TABLE public.book_category (
    book_id integer NOT NULL,
    category_id integer NOT NULL
);

CREATE TABLE public.category (
    id integer NOT NULL,
    name character varying(255)
);

ALTER TABLE public.category ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.category_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);

CREATE TABLE public.profile (
    email character varying(255) NOT NULL,
    phone bigint NOT NULL
);

CREATE TABLE public.users (
    id integer NOT NULL,
    name character varying(255),
    profile_email character varying(255),
    password character varying(255),
    role character varying(255),
    CONSTRAINT users_role_check CHECK (((role)::text = ANY ((ARRAY['ADMIN'::character varying, 'LIBRARIAN'::character varying, 'MEMBER'::character varying])::text[])))
);

ALTER TABLE public.users ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.users_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);

ALTER TABLE ONLY public.author
    ADD CONSTRAINT author_pkey PRIMARY KEY (id);

ALTER TABLE ONLY public.book
    ADD CONSTRAINT book_pkey PRIMARY KEY (id);

ALTER TABLE ONLY public.category
    ADD CONSTRAINT category_pkey PRIMARY KEY (id);

ALTER TABLE ONLY public.profile
    ADD CONSTRAINT profile_pkey PRIMARY KEY (email);

ALTER TABLE ONLY public.users
    ADD CONSTRAINT uk3ikrpg3td8y2snajjl0qn3bef UNIQUE (profile_email);

ALTER TABLE ONLY public.users
    ADD CONSTRAINT users_pkey PRIMARY KEY (id);

ALTER TABLE ONLY public.users
    ADD CONSTRAINT fk7lguc5lutpy3ngbf5ehwia2w7 FOREIGN KEY (profile_email) REFERENCES public.profile(email);

ALTER TABLE ONLY public.book
    ADD CONSTRAINT fk9cv1tt952k857xoia51k1vj12 FOREIGN KEY (user_id) REFERENCES public.users(id);

ALTER TABLE ONLY public.book_category
    ADD CONSTRAINT fkam8llderp40mvbbwceqpu6l2s FOREIGN KEY (category_id) REFERENCES public.category(id);

ALTER TABLE ONLY public.book
    ADD CONSTRAINT fkklnrv3weler2ftkweewlky958 FOREIGN KEY (author_id) REFERENCES public.author(id);

